'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {me:null, company:null, csrf:'', page:document.body.dataset.page};
const main = $('#main');
const label = s => t(String(s || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()));
const pill = value => `<span class="pill ${esc(value)}">${esc(label(value))}</span>`;
const money = (v, c='EUR') => v == null ? t("Value not provided") : new Intl.NumberFormat(I18N.language,{style:'currency',currency:c || 'EUR',maximumFractionDigits:0}).format(v);
const date = v => v && !Number.isNaN(Date.parse(v)) ? new Date(v).toLocaleDateString(I18N.language,{day:'numeric',month:'short',year:'numeric'}) : t("Not provided");
function toast(message){const node=$('#toast');node.textContent=I18N.generated(message);node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,5500);}
async function api(path, options={}){
  const headers = {...options.headers};
  if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  if(options.method && options.method!=='GET') headers['X-CSRF-Token']=state.csrf;
  const response=await fetch('/api/v1'+path,{...options,headers});
  if(!response.ok){let data;try{data=await response.json();}catch{data={};}if(response.status===401 && state.page!=='login'){location.href='/login';}throw new Error(I18N.error(data,response.status));}
  return response.json();
}
function on(selector,event,fn){const node=$(selector);if(node)node.addEventListener(event,async e=>{try{await fn(e);}catch(error){toast(error instanceof SyntaxError?t('Check the form values and try again.'):error.message);}});}
function form(selector,fn){on(selector,'submit',async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);if(b)b.disabled=true;try{await fn(new FormData(e.target),e.target);}finally{if(b)b.disabled=false;}});}
function field(name,title,value='',type='text',help=''){return `<div class="field"><label for="${esc(name)}">${esc(title)}</label><input id="${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''}>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function area(name,title,value=''){return `<div class="field full"><label for="${name}">${esc(title)}</label><textarea id="${name}" name="${name}">${esc(value)}</textarea></div>`;}
function header(title,subtitle,action='',eyebrow='YOUR WORKSPACE'){return `<div class="page-header"><div><div class="eyebrow">${esc(t(eyebrow))}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon">⌕</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;}
function modal(title,content){$('#modal-content').innerHTML=`<h2>${esc(title)}</h2>${content}`;$('#modal').showModal();}
function card(n){return `<a class="opportunity-card" href="/opportunities/${esc(n.id)}"><div class="card-top"><div class="card-meta"><span class="country-symbol">${esc(n.country||'EU')}</span>${esc(n.country||t("Europe"))}<span>·</span>${n.source==='DEMO'?`<span class="pill demo">${htmlMessage("Example data")}</span>`:t('TED opportunity')}</div>${pill(n.decision)}</div><h3>${esc(n.title)}</h3><p class="buyer">${esc(n.buyer||t("Buyer not provided"))}</p><div class="card-bottom"><span><strong>${esc(money(n.value,n.currency))}</strong></span><span>${htmlMessage("◷ {0}   ↗",n.deadline?esc(date(n.deadline)):t("Deadline needs review"))}</span></div></a>`;}
async function download(path,filename,headers={}){const r=await fetch('/api/v1'+path,{headers});if(!r.ok)throw new Error(t("Export unavailable or access denied."));const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function sourceModal(req){modal(t("Source evidence"),`<p class="subtle">${htmlMessage("{0} · {1} · extraction confidence {2}%",esc(req.source_locator),esc(req.verification_state),Math.round(req.confidence*100))}</p><small>${htmlMessage("Original source material")}</small><pre translate="no">${esc(req.text)}</pre><p class="subtle">${htmlMessage("The original source remains authoritative. Corrections are separate tenant-specific overlays.")}</p>`);}

async function login(){
  document.body.classList.add('login-mode');
  main.innerHTML=`<div class="login-layout"><section class="login-art"><a class="brand" href="/login"><img src="/static/mark.svg" width="38" height="38" alt="">Orqelis<span class="brand-dot">®</span></a><div class="login-copy"><div class="eyebrow">${htmlMessage("A BETTER WAY TO BID")}</div><h1>${htmlMessage("The right contract.")}<br>${htmlMessage("The evidence to")}<br><em>${htmlMessage("go after it.")}</em></h1><p>${htmlMessage("Turn European procurement opportunities into clear, confident decisions for your business.")}</p><div class="login-matrix"><div><strong>${htmlMessage("Find your fit")}</strong><small>${htmlMessage("Authoritative TED opportunities")}</small></div><div><strong>${htmlMessage("Prove your case")}</strong><small>${htmlMessage("Evidence-backed eligibility")}</small></div><div><strong>${htmlMessage("Bid with clarity")}</strong><small>${htmlMessage("Transparent effort and cost")}</small></div></div></div><small>${htmlMessage("Built for ambitious European businesses.")}</small></section><section class="login-form"><div><div class="eyebrow">${htmlMessage("WELCOME TO YOUR NEXT OPPORTUNITY")}</div><h2>${htmlMessage("Make your next bid count.")}</h2><p>${htmlMessage("Create your workspace or sign back in.")}</p><form id="login-form">${field('name',t("Your name"),'','text')}${field('email',t("Work email"),'','email')}<button type="submit" class="primary">${htmlMessage("Continue with email   →")}</button></form><div id="login-code"></div>${document.body.dataset.authProvider==='local'?`<div class="notice info spacerless">${htmlMessage("Local development workspace. Sign-in uses a one-time code displayed here.")}</div>`:''}<div class="login-legal">${htmlMessage("For business use. By continuing, you accept the")} <a href="/legal/terms">${htmlMessage("Terms")}</a> ${htmlMessage("and acknowledge the")} <a href="/legal/privacy">${htmlMessage("Privacy Policy")}</a>.</div></div></section></div>`;
  $('#email').required=true;
  form('#login-form',async data=>{
    const email=data.get('email');
    const result=await api('/auth/request',{method:'POST',body:Object.fromEntries(data)});
    window.OrqelisAnalytics?.event('auth_start');
    $('#login-code').innerHTML=`<form id="verify-form"><div class="notice info">${esc(t(result.message))}</div>${field('token',t("One-time sign-in code"),result.development_code||'')}<button type="submit" class="primary">${htmlMessage("Open your workspace →")}</button></form>`;
    $('#login-form').hidden=true;
    $('#token').autocomplete='one-time-code';
    $('#token').required=true;
    if(result.provider==='supabase'){ $('#token').inputMode='numeric'; $('#token').pattern='[0-9]{6,10}'; $('#token').maxLength=10; }
    $('#token').focus();
    form('#verify-form',async d=>{
      const body={token:d.get('token')};
      if(result.provider==='supabase')body.email=email;
      const verified=await api('/auth/verify',{method:'POST',body});
      await window.OrqelisAnalytics?.event(verified.account_created?'sign_up':'login');
      location.href=verified.organization_id?'/dashboard':'/onboarding';
    });
  });
}

async function onboarding(){
  let step=1;let profile=state.company?.profile || {};let orgName=state.company?.name || '';
  const render=()=>{
    main.innerHTML=`<div class="onboarding"><div class="eyebrow">${htmlMessage("LET’S FIND YOUR FIT")}</div><h1>${htmlMessage("A little context.")}<br>${htmlMessage("Much better decisions.")}</h1><p class="subtle spacer">${htmlMessage("Build your company profile in a few short steps. You can refine it anytime.")}</p><div class="spacer"></div><div class="step-indicator">${[1,2,3,4,5].map(n=>`<span class="${n<=step?'active':''}"></span>`).join('')}</div><div class="panel"><div class="step-label">${htmlMessage("STEP {0} OF 5",step)}</div><form id="onboard-form">${step===1?`<h2>${htmlMessage("Your company, at a glance")}</h2><div class="spacer"></div>${field('name',t("Company name"),orgName)}${field('country',t("Home country code"),profile.country||'','text',t("Use TED country codes, for example DEU, FRA, NLD or IRL."))}${field('employee_band',t("Employee band"),profile.employee_band||'5–25')}`:step===2?`<h2>${htmlMessage("What do you do best?")}</h2><div class="spacer"></div>${area('services',t("Your services"),profile.services||'')}${field('cpv_interests',t('CPV interests'),(profile.cpv_interests||[]).join(', '),'text',t("Comma-separated codes. IT: 72000000; consulting: 79400000; construction: 45000000."))}`:step===3?`<h2>${htmlMessage("Where can you deliver?")}</h2><div class="spacer"></div>${field('operating_countries',t("Operating countries"),(profile.operating_countries||[]).join(', '),'text',t("Comma-separated TED country codes."))}${field('languages',t("Working languages"),(profile.languages||[]).join(', '),'text',t("Use language codes such as ENG, DEU and FRA."))}`:step===4?`<h2>${htmlMessage("What makes a bid worthwhile?")}</h2><div class="spacer"></div><div class="form-grid">${field('min_contract',t("Minimum contract value"),profile.min_contract||0,'number')}${field('max_contract',t("Maximum practical contract value"),profile.max_contract||1000000,'number')}${field('hourly_cost',t("Loaded hourly staff cost"),profile.hourly_cost??60,'number')}${field('bid_hours_per_day',t("Bid-team hours available per day"),profile.bid_hours_per_day??2,'number')}</div>${field('currency',t("Currency"),profile.currency||'EUR')}`:`<h2>${htmlMessage("Your profile is ready.")}</h2><div class="spacer"></div><p class="subtle">${htmlMessage("Evidence turns a company claim into a supported decision. Add your certificates, insurance or financial summaries to the evidence vault when you’re ready.")}</p><div class="notice info spacer">${htmlMessage("Your profile is self-declared. We will not treat it as verified documentary evidence.")}</div>`}<div class="form-actions">${step>1?`<button class="secondary" type="button" id="back-step">${htmlMessage("Back")}</button>`:''}<button type="submit" class="primary">${step===5?t("Explore opportunities"):t("Continue")} →</button></div></form></div><div class="spacer"></div><details><summary class="subtle">${htmlMessage("Joining an existing team?")}</summary><form id="join-form">${field('token',t("Invitation code"))}<button class="secondary" type="submit">${htmlMessage("Join workspace")}</button></form></details></div>`;
    on('#back-step','click',()=>{step--;render();});
    form('#join-form',async d=>{await api('/memberships/accept',{method:'POST',body:{token:d.get('token')}});location.href='/dashboard';});
    form('#onboard-form',async d=>{const values=Object.fromEntries(d);if(step===1){orgName=values.name;if(!state.me.organization_id){const o=await api('/organizations',{method:'POST',body:{name:orgName}});state.me.organization_id=o.id;const c=await api('/company');profile=c.profile;}delete values.name;}
      for(const key of ['cpv_interests','operating_countries','languages'])if(key in values)values[key]=values[key].split(',').map(s=>s.trim()).filter(Boolean);
      for(const key of ['min_contract','max_contract','hourly_cost','bid_hours_per_day'])if(key in values)values[key]=Number(values[key]);
      profile={...profile,...values};if(step<5){await api('/company',{method:'PUT',body:profile});step++;render();}else {await window.OrqelisAnalytics?.event('onboarding_complete');location.href='/opportunities';}
    });
  };render();
}

async function dashboard(){
  const [opps,docs,evidence,alerts]=await Promise.all([api('/opportunities?limit=100'),api('/documents'),api('/evidence'),api('/notifications')]);
  const candidates=opps.items.filter(n=>['BID','STRONG_BID'].includes(n.decision));
  const conditional=opps.items.filter(n=>n.decision==='CONDITIONAL_BID');
  const approaching=opps.items.filter(n=>n.deadline&&new Date(n.deadline)>new Date()&&(new Date(n.deadline)-new Date())/86400000<=14);
  const expiry=evidence.filter(e=>e.valid_until&&new Date(e.valid_until)-new Date()<30*86400000);
  const name=state.me.name.split(' ')[0];
  main.innerHTML=header(t("A clearer view, {0}.",name),t("Your next opportunity starts with a well-informed decision."),`<span class="date-tag">${htmlMessage("◷   {0}",date(new Date().toISOString()))}</span>`,'YOUR BID BRIEFING')+
    `<section class="hero"><div><div class="eyebrow">${htmlMessage("LESS SEARCHING. BETTER DECISIONS.")}</div><h2>${htmlMessage("Find the contracts worth")}<br>${htmlMessage("putting your name on.")}</h2><p>${htmlMessage("Explore public tenders, check your evidence, and see what it would really take to bid.")}</p><a class="primary" href="/opportunities">${htmlMessage("Explore opportunities   ↗")}</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span>↗</span><i></i></div></div></section>
    <div class="stats">${[[t("Opportunities in view"),opps.items.length,t("From your available notice library"),'⌕'],[t("Strong candidates"),candidates.length,t("Supported by your latest assessments"),'↗'],[t("Conditional candidates"),conditional.length,t("Resolve the conditions before bidding"),'◇'],[t("Approaching deadlines"),approaching.length,t("Within the next 14 days"),'◷']].map(([t,v,n,i])=>`<div class="stat"><div class="stat-label">${t}<span>${i}</span></div><strong class="stat-value">${v}</strong><p class="stat-note">${n}</p></div>`).join('')}</div>
    <div class="content-grid"><section><div class="section-heading"><div><h2>${htmlMessage("On your opportunity radar")}</h2><p>${htmlMessage("A focused starting point for your next review.")}</p></div><a href="/opportunities" class="text-link">${htmlMessage("View all ↗")}</a></div><div class="panel">${opps.items.length?opps.items.slice(0,5).map(card).join(''):empty(t("Your next opportunity is out there"),t("Sync official TED notices to start exploring contracts. You can search while existing records remain available."), `<button class="primary" id="sync-empty">${htmlMessage("Sync TED notices ↻")}</button>`)}</div><p class="source-note">${htmlMessage("Source: TED / Publications Office of the European Union. Example records, when loaded, are explicitly labeled. Assessments are advisory and never certify eligibility.")}</p></section>
    <aside><div class="panel panel-pad"><div class="section-heading"><h3>${htmlMessage("Your evidence readiness")}</h3><span>↗</span></div><div class="checklist">${[[!!state.company.profile.country,t("Company basics added")],[!!state.company.profile.services,t("Services and focus defined")],[docs.some(d=>d.status==='READY'),t("Evidence documents uploaded")],[evidence.some(e=>e.state==='USER_CONFIRMED'),t("Documentary evidence confirmed")]].map(([done,text],index)=>`<a href="${index>=2?'/evidence':'/company'}" class="check-row ${done?'done':''}"><span>${done?'✓':'·'}</span><span>${esc(text)}</span></a>`).join('')}</div><div class="spacer"></div><a href="/evidence" class="text-link">${htmlMessage("Strengthen your profile →")}</a></div><div class="panel panel-pad"><h3>${htmlMessage("Needs your attention")}</h3>${expiry.length?expiry.slice(0,2).map(e=>`<a href="/evidence" class="side-item"><div class="mini-icon">◷</div><h3>${esc(e.capability)}</h3><p>${htmlMessage("Evidence expires {0}",date(e.valid_until))}</p></a>`).join(''):''}${alerts.length?alerts.slice(0,2).map(a=>`<div class="side-item"><h3>${esc(I18N.generated(a.title))}</h3><p>${esc(I18N.generated(a.body))}</p><small>${date(a.created_at)}</small></div>`).join(''):`<div class="side-item"><div class="mini-icon">✓</div><h3>${htmlMessage("Nothing urgent right now")}</h3><p>${htmlMessage("Watch an opportunity to receive material changes and deadline alerts.")}</p></div>`}<div class="spacer"></div><a href="/notifications" class="text-link">${htmlMessage("All notifications →")}</a></div></aside></div>`;
  on('#sync-empty','click',sync);
}

async function sync(){const result=await api('/sources/ted/sync',{method:'POST'});toast(t("TED sync {0}. The worker will import notices; refresh shortly.",result.status.toLowerCase()));}
async function opportunityList(saved=false){
  main.innerHTML=header(saved?t("Your bid pipeline"):t("Find your next opportunity"),saved?t("Saved and watched opportunities, ready for your team’s next move."):t("Authoritative public tenders. A clear path from discovery to decision."),`<button id="sync-ted" class="secondary">${htmlMessage("↻   Sync TED notices")}</button>`,saved?'FOCUS YOUR EFFORT':'EUROPEAN PROCUREMENT')+`<form id="search-form" class="toolbar"><input aria-label="${htmlMessage("Search opportunities")}" name="q" placeholder="${htmlMessage("Search by service, keyword or buyer…")}"><input aria-label="${htmlMessage("Country filter")}" name="country" placeholder="${htmlMessage("Country code, e.g. DEU")}"><input aria-label="${htmlMessage("CPV filter")}" name="cpv" placeholder="${htmlMessage("CPV code")}"><button type="submit" class="primary">${htmlMessage("Search →")}</button></form><div id="opportunity-results"></div><div class="spacer"></div><button id="load-more" class="secondary" hidden>${htmlMessage("Load more opportunities")}</button><p class="source-note">${htmlMessage("Current library results are shown with source and retrieval timestamps. Search metadata alone cannot establish full eligibility.")}</p>`;
  let cursor=null;let filters={};
  const load=async append=>{const params=new URLSearchParams({...filters,saved:String(saved),...(append&&cursor?{cursor}:{})});const data=await api('/opportunities?'+params);const host=$('#opportunity-results');if(!append)host.innerHTML=`<div class="search-grid"></div>`;if(data.items.length){$('.search-grid',host).insertAdjacentHTML('beforeend',data.items.map(card).join(''));}else if(!append)host.innerHTML=`<div class="panel">${empty(t("No opportunities in this view"),t("Try a broader search or sync TED notices. With an empty library, run the worker to process your sync request."))}</div>`;cursor=data.next_cursor;$('#load-more').hidden=!cursor;};
  form('#search-form',async d=>{filters=Object.fromEntries(d);await load(false);});on('#load-more','click',()=>load(true));on('#sync-ted','click',sync);await load(false);
}

async function opportunityDetail(id){
  const [detail,current,members,watches]=await Promise.all([api('/opportunities/'+id),api('/opportunities/'+id+'/analysis'),api('/memberships'),api('/watchlist')]);
  window.OrqelisAnalytics?.event('opportunity_view');
  const n=detail.facts;let assessment=current;const watch=watches.find(w=>w.notice_id===id);
  const render=()=>{
    const a=assessment.result;
    main.innerHTML=`<a class="text-link" href="/opportunities">${htmlMessage("← All opportunities")}</a><div class="spacer"></div><div class="page-header"><div><div class="eyebrow">${esc(n.country||t('EUROPE'))} · ${detail.source==='DEMO'?t('EXAMPLE DATA'):'TED '+esc(n.publication_number)}</div><h1 class="detail-title" translate="no">${esc(n.title)}</h1><p>${htmlMessage("{0} · Published {1}",esc(n.buyer),date(n.published))}</p></div></div><div class="button-row"><button class="primary" id="analyze">${a?t("Recompute assessment"):t("Assess this opportunity")} ✦</button><button class="secondary" data-watch="WATCH">${watch?.state==='WATCH'?'✓ '+t('Watching'):'◇ '+t('Watch changes')}</button><button class="secondary" data-watch="SAVED">${htmlMessage("Save to pipeline")}</button><button class="secondary" id="dismiss">${htmlMessage("Dismiss")}</button><button class="secondary" id="assign">${htmlMessage("Assign")}</button>${a?`<button class="secondary" id="export-report">${htmlMessage("Export report ↓")}</button><button class="secondary" id="print-report">${htmlMessage("Print / PDF")}</button>`:''}<button class="secondary" id="outcome">${htmlMessage("Record outcome")}</button></div><div class="spacer"></div>${assessment.stale?`<div class="notice">${htmlMessage("This assessment is out of date. Recompute against the current notice and company evidence.")}</div>`:''}
    <div class="detail-grid"><section>${a?`<section class="decision-banner ${esc(a.decision)}"><div class="eyebrow">${htmlMessage("YOUR EVIDENCE-BASED DECISION")}</div>${pill(a.eligibility)}<h2>${esc(label(a.decision))}</h2><p>${esc(I18N.generated(a.explanation))}</p></section><div class="score-grid">${[[t("Feasibility"),a.feasibility,t("Weighted practical fit")],[t("Attractiveness"),a.attractiveness,t("Transparent business assumptions")],[t("Evidence coverage"),a.coverage,`${a.coverage_numerator} / ${a.coverage_denominator} ${t("weighted points")}`]].map(([t,v,note])=>`<div class="score-card"><small>${t}</small><strong>${v}<small> / 100</small></strong><small>${note}</small></div>`).join('')}</div><div class="panel"><div class="panel-heading"><h3>${htmlMessage("Requirement & evidence matrix")}</h3><span class="subtle">${htmlMessage("{0} requirements",a.requirements.length)}</span></div>${a.requirements.length?`<div class="table-wrap"><table class="matrix"><thead><tr><th>${htmlMessage("REQUIREMENT / SOURCE")}</th><th>${htmlMessage("RESULT")}</th><th>${htmlMessage("EVIDENCE & NEXT STEP")}</th></tr></thead><tbody>${a.requirements.map((r,i)=>`<tr><td><strong>${esc(r.requirement.capability)}</strong><p translate="no">${esc(r.requirement.text)}</p><small>${r.requirement.hard_gate?t("Mandatory gate"):'Non-mandatory'}${r.requirement.user_correction?' · '+t('User correction'):''}</small><br><button class="source-button" data-source="${i}">${htmlMessage("View source ↗")}</button> · <button class="source-button" data-correct="${i}">${htmlMessage("Correct classification")}</button></td><td>${pill(r.state)}</td><td><p>${esc(I18N.generated(r.reason))}</p>${r.evidence_ids.map(e=>`<small>${htmlMessage("Evidence {0}",esc(e.slice(0,8)))}</small>`).join('')}<p>${esc(I18N.generated(r.next_action||''))}</p></td></tr>`).join('')}</tbody></table></div>`:empty(t("Full requirements need review"),t("No supported selection criteria were extracted from this metadata. Open the authoritative source and review the full tender dossier."))}</div>${a.lots?.length?`<div class="panel panel-pad"><h3>${htmlMessage("Lot assessments")}</h3>${a.lots.map(l=>`<div class="side-item"><h3>${htmlMessage("Lot {0} {1}",esc(l.lot_id),pill(l.decision))}</h3><p>${esc(I18N.generated(l.explanation))}</p><small>${htmlMessage("Coverage {0}% · {1} requirements",l.coverage,l.requirements.length)}</small></div>`).join('')}</div>`:''}<div class="panel panel-pad"><h3>${htmlMessage("Highest-impact next actions")}</h3><ul class="bullet-list">${(a.missing_evidence.length?a.missing_evidence:[t("Review source completeness, assumptions and submission documentation.")]).map(x=>`<li>${esc(I18N.generated(x))}</li>`).join('')}</ul><div class="spacer"></div><a class="text-link" href="/evidence">${htmlMessage("Open evidence vault →")}</a></div><div class="panel panel-pad"><h3>${htmlMessage("Why these scores?")}</h3><div class="table-wrap"><table class="matrix"><thead><tr><th>${htmlMessage("FEASIBILITY COMPONENT")}</th><th>${htmlMessage("SCORE")}</th><th>${htmlMessage("WEIGHT")}</th></tr></thead><tbody>${Object.entries(a.components).map(([k,v])=>`<tr><td>${esc(label(k))}<p>${esc(I18N.generated(v.basis))}</p></td><td>${v.score}</td><td>${Math.round(v.weight*100)}%</td></tr>`).join('')}</tbody></table></div><p class="source-note">${htmlMessage("Algorithm {0} · source version {1} · company version {2}. Feasibility is the rounded sum of component score × weight. These are heuristic scores, not a probability of winning.",esc(a.algorithm_version),esc(a.notice_version),a.company_capability_version)}</p></div>`:`<div class="panel">${empty(t("Start with the evidence"),t("Run an assessment to see eligibility, missing evidence, effort and cross-border considerations."))}</div>`}<div class="panel panel-pad"><h3>${htmlMessage("Tender description")}</h3><small class="source-note">${htmlMessage("Original source material")}</small><p class="subtle spacer">${esc(n.description||t("Detailed description is not included in the current source metadata. Consult the official notice."))}</p><div class="spacer"></div><h3>${htmlMessage("Change history")}</h3>${detail.changes.length?detail.changes.map(c=>`<div class="side-item">${pill(c.class)} <small>${date(c.created_at)}</small><p>${esc(Object.keys(c.fields).join(', '))}</p></div>`).join(''):`<p class="source-note">${htmlMessage("No changes observed in the locally retained version history.")}</p>`}</div></section>
    <aside><div class="panel panel-pad"><h3>${htmlMessage("Source facts")}</h3><dl class="fact-list">${[[t("Estimated value"),money(n.value,n.currency)],[t("Deadline"),n.deadline?date(n.deadline):t("Not verified")],[t("Country"),n.country||t("Not provided")],['CPV',(n.cpv_codes||[]).join(', ')||t("Not provided")],[t("Notice version"),n.source_version],[t("Source completeness"),n.completeness_score+'%'],[t("Retrieved"),date(detail.fetched_at)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="spacer"></div>${detail.source==='TED'?`<a class="primary" href="${esc(n.source_url)}" target="_blank" rel="noopener noreferrer">${htmlMessage("Official TED notice ↗")}</a>`:`<div class="notice">${htmlMessage("This is a labeled demonstration fixture, not a published opportunity.")}</div>`}<p class="source-note">${htmlMessage("Source facts and extracted statements are distinct from user assumptions.")}</p></div>${a?`<div class="panel panel-pad"><h3>${htmlMessage("Bid effort & cost")}</h3><dl class="fact-list"><div><dt>${htmlMessage("Estimated effort")}</dt><dd>${htmlMessage("{0} hours",a.effort_hours.join('–'))}</dd></div><div><dt>${htmlMessage("Estimated bid cost")}</dt><dd>${money(a.cost_range[0],a.cost_currency)}–${money(a.cost_range[1],a.cost_currency)}</dd></div><div><dt>${htmlMessage("Available capacity")}</dt><dd>${a.available_hours==null?t("Deadline unknown"):Math.round(a.available_hours)+' '+t('hours')}</dd></div><div><dt>${htmlMessage("Hourly assumption")}</dt><dd>${money(a.cost_inputs.hourly_cost,a.cost_currency)}</dd></div></dl><p class="source-note">${htmlMessage("{0} Contract value is revenue, not profit.",esc(a.unmodeled_costs.map(I18N.generated).join(' ')))}</p></div><div class="panel panel-pad"><h3>${htmlMessage("Cross-border considerations")}</h3>${a.friction.length?`<ul class="bullet-list">${a.friction.map(f=>`<li>${esc(I18N.generated(f.reason))} <small>${htmlMessage("Source: {0}",esc(f.source))}</small></li>`).join('')}</ul>`:`<p class="source-note">${htmlMessage("No additional friction identified from the available source facts. Missing facts remain unknown.")}</p>`}</div><div class="panel panel-pad"><h3>${htmlMessage("Uncertainty & sensitivity")}</h3><p class="source-note">${htmlMessage("Analysis confidence {0}% · {1} under effort assumptions.",a.confidence,esc(a.sensitivity))}</p><ul class="bullet-list">${a.uncertainty.map(u=>`<li>${esc(I18N.generated(u))}</li>`).join('')}</ul></div>`:''}</aside></div>`;
    on('#analyze','click',async e=>{window.OrqelisAnalytics?.event('assessment_start');e.target.disabled=true;try{assessment=await api('/opportunities/'+id+'/analysis',{method:'POST'});window.OrqelisAnalytics?.event('assessment_complete');if(['BID','STRONG_BID','NO_BID'].includes(assessment.result?.decision))window.OrqelisAnalytics?.event('decision_complete');render();toast(t("Assessment updated using your current evidence."));}finally{e.target.disabled=false;}});
    $$('[data-watch]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/watchlist/'+id,{method:'PUT',body:{state:b.dataset.watch}});toast(t("Pipeline updated."));}catch(e){toast(e.message);}}));
    on('#dismiss','click',()=>{modal(t("Dismiss opportunity"),`<form id="dismiss-form"><div class="field"><label for="reason">${htmlMessage("Reason")}</label><select name="reason" id="reason">${['Irrelevant scope','Too small','Too large','Geography','Deadline','Certification','Incumbent','Strategic mismatch'].map(v=>`<option value="${esc(v)}">${esc(t(v))}</option>`).join('')}</select></div><button class="primary" type="submit">${htmlMessage("Dismiss opportunity")}</button></form>`);form('#dismiss-form',async d=>{await api('/watchlist/'+id,{method:'PUT',body:{state:'DISMISSED',reason:d.get('reason')}});$('#modal').close();toast(t("Opportunity dismissed."));});});
    on('#assign','click',()=>{modal(t("Assign to your team"),`<form id="assign-form"><div class="field"><label for="assignee">${htmlMessage("Team member")}</label><select name="assigned_to" id="assignee">${members.map(m=>`<option value="${esc(m.user_id)}">${esc(m.email)} (${esc(label(m.role))})</option>`).join('')}</select></div><button class="primary" type="submit">${htmlMessage("Assign opportunity")}</button></form>`);form('#assign-form',async d=>{await api('/watchlist/'+id,{method:'PUT',body:{state:'SAVED',assigned_to:d.get('assigned_to')}});$('#modal').close();toast(t("Assigned to team member."));});});
    on('#export-report','click',()=>download('/exports/analyses/'+assessment.id,'decision-report.json'));
    on('#print-report','click',()=>window.print());
    $$('[data-source]').forEach(b=>b.addEventListener('click',()=>sourceModal(a.requirements[Number(b.dataset.source)].requirement)));
    $$('[data-correct]').forEach(b=>b.addEventListener('click',()=>{const r=a.requirements[Number(b.dataset.correct)].requirement;modal(t("Correct requirement classification"),`<p class="subtle">${esc(r.text)}</p><div class="spacer"></div><form id="correction-form"><div class="field"><label for="hard_gate">${htmlMessage("Requirement classification")}</label><select name="hard_gate" id="hard_gate"><option value="true">${htmlMessage("Mandatory")}</option><option value="false">${htmlMessage("Non-mandatory")}</option></select></div>${area('reason',t("Reason and source support"))}<button type="submit" class="primary">${htmlMessage("Save correction & recompute")}</button></form>`);$('#hard_gate').value=String(r.hard_gate);form('#correction-form',async d=>{await api('/opportunities/'+id+'/corrections',{method:'POST',body:{requirement_id:r.id,hard_gate:d.get('hard_gate')==='true',reason:d.get('reason')}});assessment=await api('/opportunities/'+id+'/analysis',{method:'POST'});$('#modal').close();render();});}));
    on('#outcome','click',()=>{modal(t("Record your bid outcome"),`<p class="subtle">${htmlMessage("Outcomes are private to your organization and never treated as a calibrated win model.")}</p><form id="outcome-form"><div class="field"><label for="status">${htmlMessage("Outcome")}</label><select name="status" id="status">${['NOT_SUBMITTED','SUBMITTED','SHORTLISTED','WON','LOST'].map(s=>`<option value="${s}">${label(s)}</option>`).join('')}</select></div>${field('actual_hours',t("Actual bid hours"),'','number')}${field('actual_cost',t("Actual bid cost"),'','number')}<button type="submit" class="primary">${htmlMessage("Save outcome")}</button></form>`);form('#outcome-form',async d=>{await api('/opportunities/'+id+'/outcome',{method:'POST',body:{status:d.get('status'),actual_hours:d.get('actual_hours')?Number(d.get('actual_hours')):null,actual_cost:d.get('actual_cost')?Number(d.get('actual_cost')):null}});$('#modal').close();toast(t("Outcome recorded."));});});
  };render();
}

async function company(){
  const p=state.company.profile;
  main.innerHTML=header(t("The company behind the bid."),t("Keep your capabilities and commercial assumptions current. Evidence is confirmed separately."),pill('USER_DECLARED'),'COMPANY PROFILE')+`<form id="company-form"><div class="panel panel-pad"><div class="form-section"><h2>${htmlMessage("Company & capabilities")}</h2><p>${htmlMessage("Profile statements help assess fit. They do not establish hard eligibility.")}</p><div class="form-grid">${field('country',t("Home country"),p.country)}${field('employee_band',t("Employee band"),p.employee_band)}${field('operating_countries',t("Operating country codes"),(p.operating_countries||[]).join(', '))}${field('languages',t("Working language codes"),(p.languages||[]).join(', '))}${field('cpv_interests',t('CPV interests'),(p.cpv_interests||[]).join(', '))}${field('revenue_band',t("Revenue band"),p.revenue_band)}${area('services',t("Services"),p.services)}${area('products',t("Products"),p.products)}${area('staff_capabilities',t("Staff qualifications and capabilities"),p.staff_capabilities)}${area('past_projects',t("Previous projects, values and dates"),p.past_projects)}${field('certifications',t("Declared certifications"),(p.certifications||[]).join(', '))}${field('insurance',t("Insurance summary"),p.insurance)}${field('delivery_model',t("Delivery model"),p.delivery_model)}${field('security_clearances',t("Security clearances"),p.security_clearances)}</div></div><div class="form-section"><h2>${htmlMessage("Your bid economics")}</h2><p>${htmlMessage("Transparent assumptions used for estimates. Use your loaded staff cost, including overhead.")}</p><div class="form-grid">${field('min_contract',t("Minimum worthwhile contract"),p.min_contract,'number')}${field('max_contract',t("Maximum practical contract"),p.max_contract,'number')}${field('preferred_contract',t("Preferred contract value"),p.preferred_contract,'number')}${field('currency',t("Currency"),p.currency)}${field('hourly_cost',t("Loaded hourly cost"),p.hourly_cost,'number')}${field('external_bid_cost',t("Known external bid costs"),p.external_bid_cost,'number')}${field('bid_hours_per_day',t("Bid-team hours per day"),p.bid_hours_per_day,'number')}${field('expected_margin',t("Expected gross margin (%)"),p.expected_margin??'','number')}${field('availability_factor',t("Availability factor (0–1)"),p.availability_factor,'number')}${field('effort_multiplier',t("Effort multiplier from experience (0.25–5)"),p.effort_multiplier,'number')}</div><label><input type="checkbox" name="partner_willingness" ${p.partner_willingness?'checked':''}> ${htmlMessage("Open to consortium or subcontracting opportunities")}</label></div><div class="form-actions"><button type="submit" class="primary">${htmlMessage("Save company profile →")}</button></div></div></form>`;
  form('#company-form',async d=>{const value={...p,...Object.fromEntries(d)};for(const k of ['operating_countries','languages','cpv_interests','certifications'])value[k]=value[k].split(',').map(v=>v.trim()).filter(Boolean);for(const k of ['min_contract','max_contract','preferred_contract','hourly_cost','external_bid_cost','bid_hours_per_day','availability_factor','effort_multiplier'])value[k]=Number(value[k]);value.expected_margin=value.expected_margin===''?null:Number(value.expected_margin);value.partner_willingness=d.has('partner_willingness');await api('/company',{method:'PUT',body:value});state.company.profile=value;toast(t("Profile saved. Affected assessments are queued for recomputation."));});
}

async function evidencePage(){
  const [docs,evidence]=await Promise.all([api('/documents'),api('/evidence')]);
  main.innerHTML=header(t("Your proof, in one place."),t("Turn capabilities into source-backed evidence your bid team can trust."),`<button id="add-evidence" class="primary">${htmlMessage("+ Add evidence")}</button>`,'EVIDENCE VAULT')+`<div class="notice info">${htmlMessage("Upload only what is necessary. Redact unnecessary personal information and avoid special-category personal data. Documents remain private to your organization.")}</div><div class="split"><section><div class="section-heading"><h2>${htmlMessage("Source documents")}</h2><button id="refresh-evidence" class="icon-button" aria-label="${htmlMessage("Refresh document status")}">↻</button></div><div class="panel panel-pad"><form id="upload-form"><div class="field"><label for="file">${htmlMessage("Upload a document")}</label><input id="file" name="file" type="file" accept=".pdf,.txt" required><small>${htmlMessage("Non-active PDF or UTF-8 text · Maximum 10 MB · Validation and scanning before access")}</small></div><button type="submit" class="primary">${htmlMessage("Upload securely ↑")}</button></form></div><div class="panel">${docs.length?docs.map(d=>`<div class="evidence-item"><div><h3>${esc(d.filename)}</h3><small>${htmlMessage("{0} KB · {1}",Math.round(d.size/1024),date(d.created_at))}</small><div>${pill(d.status)}</div></div><div class="evidence-actions">${d.status==='READY'?`<button class="secondary" data-preview="${d.id}">${htmlMessage("View text")}</button><button class="secondary" data-download="${d.id}">↓</button>`:''}<button class="secondary" data-delete-doc="${d.id}">${htmlMessage("Delete")}</button></div></div>`).join(''):empty(t("Start your evidence library"),t("Upload a certificate, insurance policy, financial summary or project reference."))}</div><p class="source-note">${htmlMessage("Quarantined documents are processed by the background worker. Refresh to see validation results. Scanned PDFs without readable text need a readable replacement.")}</p></section><section><div class="section-heading"><h2>${htmlMessage("Capability evidence")}</h2><span class="subtle">${htmlMessage("{0} items",evidence.length)}</span></div><div class="panel">${evidence.length?evidence.map(e=>`<div class="evidence-item"><div><h3>${esc(e.capability)}</h3><small>${e.valid_until?t('Valid until')+' '+date(e.valid_until):t("Validity not supplied")}</small><div>${pill(e.state)}</div></div><div class="evidence-actions"><button class="secondary" data-edit-evidence="${e.id}">${htmlMessage("Edit")}</button><button class="secondary" data-delete-evidence="${e.id}">${htmlMessage("Delete")}</button></div></div>`).join(''):empty(t("Capabilities need evidence"),t("Add a capability and link it to a validated document. Confirm the exact source passage to support eligibility."))}</div><div class="panel panel-pad"><h3>${htmlMessage("What does “confirmed” mean?")}</h3><div class="side-item"><h3>${htmlMessage("Unverified")}</h3><p>${htmlMessage("A claim or extraction awaiting review. It cannot pass a hard eligibility gate.")}</p></div><div class="side-item"><h3>${htmlMessage("User confirmed")}</h3><p>${htmlMessage("Your team reviewed the linked document and exact excerpt. This is not independent certification by Orqelis.")}</p></div><div class="side-item"><h3>${htmlMessage("Expired")}</h3><p>${htmlMessage("Historical evidence only. Future renewal is never assumed.")}</p></div></div></section></div>`;
  form('#upload-form',async d=>{await api('/documents',{method:'POST',body:d});toast(t("Document quarantined for validation."));await evidencePage();});on('#refresh-evidence','click',evidencePage);
  const edit=async e=>{
    modal(e?t("Edit capability evidence"):t("Add capability evidence"),`<form id="evidence-form">${field('capability',t("Capability"),e?.capability||'','text',t("Examples: ISO 27001, TURNOVER, INSURANCE, REFERENCES"))}<div class="field"><label for="document_id">${htmlMessage("Source document")}</label><select id="document_id" name="document_id"><option value="">${htmlMessage("No document — self declaration only")}</option>${docs.filter(d=>d.status==='READY').map(d=>`<option value="${d.id}" ${e?.document_id===d.id?'selected':''}>${esc(d.filename)}</option>`).join('')}</select></div><div id="selected-preview"></div><div class="form-grid">${field('value',t("Numeric value"),e?.data.value??'','number')}${field('currency',t("Currency"),e?.data.currency||'')}${field('valid_from',t("Valid from"),e?.valid_from||'','date')}${field('valid_until',t("Valid until"),e?.valid_until||'','date')}${field('issuer',t("Issuer"),e?.data.issuer||'')}${field('locator',t("Page or section"),e?.locator||'')}</div>${area('annual_values',t("Annual values (JSON, if required)"),JSON.stringify(e?.data.annual_values||{}))}${area('source_excerpt',t("Exact source excerpt"),e?.data.source_excerpt||'')}<div class="field"><label for="state">${htmlMessage("Verification state")}</label><select name="state" id="state"><option value="UNVERIFIED">${htmlMessage("Unverified declaration")}</option><option value="USER_CONFIRMED">${htmlMessage("I confirm the value against this document and excerpt")}</option><option value="REJECTED">${htmlMessage("Rejected")}</option></select></div><button class="primary" type="submit">${htmlMessage("Save evidence →")}</button></form>`);
    $('#state').value=['UNVERIFIED','USER_CONFIRMED','REJECTED'].includes(e?.state)?e.state:'UNVERIFIED';
    const preview=async()=>{const id=$('#document_id').value;$('#selected-preview').innerHTML=id?`<pre class="document-preview" translate="no">${esc((await api('/documents/'+id)).text)}</pre>`:'';};on('#document_id','change',preview);await preview();
    form('#evidence-form',async d=>{const body=Object.fromEntries(d);body.document_id=body.document_id||null;body.value=body.value===''?null:Number(body.value);body.currency=body.currency||null;body.valid_from=body.valid_from||null;body.valid_until=body.valid_until||null;body.annual_values=JSON.parse(body.annual_values||'{}');await api('/evidence'+(e?'/'+e.id:''),{method:e?'PUT':'POST',body});$('#modal').close();toast(t("Evidence saved. Assessments will use the updated capability version."));await evidencePage();});
  };
  on('#add-evidence','click',()=>edit(null));
  $$('[data-edit-evidence]').forEach(b=>b.addEventListener('click',()=>edit(evidence.find(e=>e.id===b.dataset.editEvidence)).catch(e=>toast(e.message))));
  $$('[data-preview]').forEach(b=>b.addEventListener('click',async()=>{try{const doc=await api('/documents/'+b.dataset.preview);modal(doc.filename,`<pre translate="no">${esc(doc.text)}</pre>`);}catch(e){toast(e.message);}}));
  $$('[data-download]').forEach(b=>b.addEventListener('click',async()=>{try{const grant=await api('/documents/'+b.dataset.download+'/access',{method:'POST'});await download('/documents/'+b.dataset.download+'/download','evidence-document',{'X-Document-Token':grant.access_token});}catch(e){toast(e.message);}}));
  const remove=(selector,key,path)=>$$(selector).forEach(b=>b.addEventListener('click',()=>{modal(t("Delete this record?"),`<p class="subtle">${htmlMessage("This removes active access and causes affected assessments to be recomputed. This action cannot be undone.")}</p><div class="spacer"></div><button class="danger" id="confirm-delete">${htmlMessage("Delete permanently")}</button>`);on('#confirm-delete','click',async()=>{await api(path+b.dataset[key],{method:'DELETE'});$('#modal').close();await evidencePage();toast(t("Record deleted."));});}));
  remove('[data-delete-doc]','deleteDoc','/documents/');remove('[data-delete-evidence]','deleteEvidence','/evidence/');
}

async function notifications(){const rows=await api('/notifications');main.innerHTML=header(t("Stay ahead of what changes."),t("Material notice changes, approaching deadlines and expiring evidence."),'','NOTIFICATIONS')+`<div class="panel">${rows.length?rows.map(n=>`<div class="notification-row ${n.read?'':'unread'}"><div class="mini-icon">♧</div><div><a href="${esc(n.href)}"><h3>${esc(I18N.generated(n.title))}</h3></a><p>${esc(I18N.generated(n.body))}</p><small>${date(n.created_at)} · ${n.delivered?t("Email delivered"):t("Available in your workspace")}</small></div>${!n.read?`<button class="secondary" data-read="${n.id}">${htmlMessage("Mark read")}</button>`:''}</div>`).join(''):empty(t("You’re all caught up"),t("Watch opportunities and add evidence to receive meaningful changes here."))}</div>`;$$('[data-read]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/notifications/'+b.dataset.read+'/read',{method:'POST'});await notifications();}catch(e){toast(e.message);}}));}

async function settingsPage(){
  const [billing,members]=await Promise.all([api('/billing'),api('/memberships')]);
  main.innerHTML=header(t("Your workspace, your control."),t("Manage your team, plan and company data."),'','WORKSPACE SETTINGS')+`<div class="settings-tabs"><a href="#plan">${htmlMessage("Plan & usage")}</a><a href="#team">${htmlMessage("Team")}</a><a href="#data">${htmlMessage("Data controls")}</a></div><section id="plan"><div class="section-heading"><h2>${htmlMessage("Plan & usage")}</h2>${pill(billing.plan)}</div><div class="notice info">${htmlMessage("Your free workspace is active. Paid subscriptions are unavailable until the operator selects and configures a payment provider and commercial terms. No charges are collected.")}</div><div class="plan-grid">${Object.entries(billing.plans).map(([k,p])=>`<div class="panel"><h3>${esc(k)}</h3><p>${htmlMessage("{0} analyses / month",p.analyses)}</p><p>${htmlMessage("{0} evidence documents",p.documents)}</p><p>${htmlMessage("{0} team members",p.members)}</p>${k===billing.plan?pill('CURRENT_PLAN'):`<small>${htmlMessage("Commercial setup pending")}</small>`}</div>`).join('')}</div><p class="refresh-note">${htmlMessage("This month: {0} analyses · {1} KB uploaded. No LLM calls are made by the deterministic engine.",billing.usage.analysis||0,Math.round((billing.usage.storage_bytes||0)/1024))}</p></section><div class="spacer"></div><div class="split"><section id="team"><div class="section-heading"><h2>${htmlMessage("Your team")}</h2></div><div class="panel">${members.map(m=>`<div class="evidence-item"><div><h3>${esc(m.email)}</h3><small>${esc(label(m.role))}</small></div>${m.role!=='OWNER'?`<button class="secondary" data-remove-member="${m.id}">${htmlMessage("Remove")}</button>`:''}</div>`).join('')}</div><div class="panel panel-pad"><h3>${htmlMessage("Invite a colleague")}</h3><div class="spacer"></div><form id="invite-form">${field('email',t("Work email"),'','email')}<div class="field"><label for="role">${htmlMessage("Role")}</label><select name="role" id="role"><option value="MEMBER">${htmlMessage("Member")}</option><option value="ADMIN">${htmlMessage("Admin")}</option><option value="VIEWER">${htmlMessage("Viewer")}</option></select></div><button class="primary" type="submit">${htmlMessage("Create invitation code")}</button></form><div id="invitation-result"></div></div></section><section id="data"><div class="section-heading"><h2>${htmlMessage("Workspace & data controls")}</h2></div><div class="panel panel-pad"><form id="switch-form"><div class="field"><label for="organization">${htmlMessage("Active organization")}</label><select id="organization" name="organization">${state.me.organizations.map(o=>`<option value="${o.id}" ${o.id===state.me.organization_id?'selected':''}>${esc(o.name)} · ${esc(label(o.role))}</option>`).join('')}</select></div><button class="secondary" type="submit">${htmlMessage("Switch workspace")}</button></form><div class="spacer"></div><a class="text-link" href="/onboarding">${htmlMessage("Create another organization →")}</a></div><div class="panel panel-pad"><h3>${htmlMessage("Take your data with you")}</h3><p class="source-note">${htmlMessage("Export your account, company profile, evidence, reports and available original documents.")}</p><button id="export-account" class="secondary">${htmlMessage("Download account archive ↓")}</button></div><div class="panel panel-pad danger-zone"><h3>${htmlMessage("Delete your account")}</h3><p class="source-note">${htmlMessage("Permanently delete active account data and sole-owned workspaces. Remove team members first. Backups expire according to the operator’s retention policy.")}</p><button id="delete-account" class="danger">${htmlMessage("Delete account…")}</button></div></section></div>`;
  form('#invite-form',async d=>{const result=await api('/memberships/invite',{method:'POST',body:Object.fromEntries(d)});$('#invitation-result').innerHTML=`<div class="notice info spacer">${esc(t(result.message))}<pre>${esc(result.invitation_code)}</pre>${htmlMessage("Valid for {0} days.",result.expires_in_days)}</div>`;});
  form('#switch-form',async d=>{await api('/organizations/'+d.get('organization')+'/switch',{method:'POST'});location.href='/dashboard';});
  on('#export-account','click',()=>download('/account/export','orqelis-account.zip'));
  on('#delete-account','click',()=>{modal(t("Permanently delete your account?"),`<form id="delete-account-form"><p class="subtle">${htmlMessage("This removes your account and any sole-owned organizations, including uploaded files and decision history.")}</p><div class="spacer"></div>${field('confirmation',t("Type DELETE to confirm"))}<button class="danger" type="submit">${htmlMessage("Permanently delete account")}</button></form>`);form('#delete-account-form',async d=>{if(d.get('confirmation')!=='DELETE')throw new Error(t("Type DELETE to confirm."));await api('/account',{method:'DELETE'});location.href='/login';});});
  $$('[data-remove-member]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/memberships/'+b.dataset.removeMember,{method:'DELETE'});await settingsPage();}catch(e){toast(e.message);}}));
}

async function boot(){
  await I18N.ready;
  if (window.orqelisAuthReady) await window.orqelisAuthReady;
  on('#close-modal','click',()=>$('#modal').close());on('#mobile-menu','click',()=>$('.sidebar').classList.toggle('open'));
  if(state.page==='login'){await login();return;}
  state.me=await api('/auth/me');state.csrf=state.me.csrf;
  $('#user-name').textContent=state.me.name;$('#user-initial').textContent=state.me.name[0]?.toUpperCase()||'Y';
  on('#logout','click',async()=>{await api('/auth/logout',{method:'POST'});location.href='/login';});
  if(state.me.organization_id){state.company=await api('/company');$('#workspace-name').textContent=state.company.name;}else if(state.page!=='onboarding'){location.href='/onboarding';return;}
  const navPage=state.page.split('/')[0];$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===navPage));$('#breadcrumb').innerHTML=`${htmlMessage("Workspace")} <span>/</span> ${esc(navPage==='dashboard'?t("Overview"):label(navPage))}`;
  if(state.company){const unread=(await api('/notifications')).filter(n=>!n.read).length;$('#unread').textContent=unread||'';}
  if(state.page==='onboarding')await onboarding();
  else if(state.page==='dashboard')await dashboard();
  else if(state.page==='opportunities')await opportunityList();
  else if(state.page.startsWith('opportunities/'))await opportunityDetail(state.page.split('/')[1]);
  else if(state.page==='watchlist')await opportunityList(true);
  else if(state.page==='company')await company();
  else if(state.page==='evidence')await evidencePage();
  else if(state.page==='notifications')await notifications();
  else if(state.page==='settings')await settingsPage();
}
boot().catch(error=>{main.innerHTML=`<div class="panel">${empty(t("We couldn’t open this view"),error.message,`<button class="primary" id="retry-page">${htmlMessage("Try again")}</button>`)}</div>`;on('#retry-page','click',()=>location.reload());});
